#[test]
fn test_the_sniff_reads_the_signature_and_nothing_else() {
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("89504e470d0a1a0a0000000d")[..])), rs_png(), "PNG");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("ffd8ffe000104a46")[..])), rs_jpeg(), "JPEG");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("49492a0008000000")[..])), rs_tiff(), "TIFF, little endian");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("4d4d002a00000008")[..])), rs_tiff(), "TIFF, big endian");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("255044462d312e37")[..])), rs_none(), "a PDF is none of them");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("89504e470d0a1a0b")[..])), rs_none(), "a PNG signature with one byte wrong");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("89504e47")[..])), rs_none(), "a PNG signature cut short");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("4949")[..])), rs_none(), "too short to say");
    crate::testport::assert_eq(rs_sniff(&crate::port::src_of_blob(&crate::testport::hex_blob("49492b0008000000")[..])), rs_none(), "BigTIFF is not read");
    crate::testport::assert_eq(rs_cpt(463, 20000), 16668, "463 px at 200 dpi is 166.68 pt");
    crate::testport::assert_eq(rs_cpt(2481, 30000), 59544, "A4 at 300 dpi, rounded");
    crate::testport::assert_eq(rs_cpt(1, 100000000), 1, "never zero");
}
